      intro: 'Darkroom एक मल्टी-ट्रैक वीडियो एडिटर है जो ब्राउज़र टैब में चलता है। आप कैनवास और फ़्रेम रेट के साथ एक प्रोजेक्ट बनाते हैं, वीडियो, इमेज और ऑडियो फ़ाइलें मीडिया बिन में डालते हैं, उन्हें एक के ऊपर एक रखे ट्रैकों पर सजाते हैं, फ़्रेम की सीमाओं पर ट्रिम और स्प्लिट करते हैं, उनकी कलर ग्रेडिंग और कीइंग करते हैं, टाइटल, ट्रांज़िशन और कैप्शन जोड़ते हैं, हर ट्रैक के मिक्सर से ऑडियो मिक्स करते हैं, और फिर तैयार टाइमलाइन हमारे रेंडर सर्वर को सौंप देते हैं, जहाँ ffmpeg पूरे एडिट को एक फ़िल्टर ग्राफ़ के रूप में बनाता है और उसे MP4 में H.264 या HEVC में एनकोड करता है, या प्रोजेक्ट केवल ऑडियो का हो तो MP3 या WAV में। जिस प्रीव्यू पर आप एडिट करते हैं, वह आपके GPU पर WebGL2 में लाइव कंपोज़िट होता है; एक्सपोर्ट को उसी प्रीव्यू से मिलाकर जाँचा जाता है, ताकि जो आपने देखा वही आपको मिले।',
