        'एक्सपोर्ट ffmpeg का एक ही इनवोकेशन है: हर सोर्स एक इनपुट है, टाइमलाइन एक filter_complex ग्राफ़ बन जाती है (trim, scale, overlay, टाइटल के लिए drawtext, eq और कलर फ़िल्टर, ऑडियो के लिए normalize=0 के साथ amix) और आउटपुट एक ही पास में एनकोड होता है। कीफ़्रेम वाले पैरामीटर ग्राफ़ पर एक sendcmd साइडकार के ज़रिए चलते हैं, जिसके लिए रेंडर होस्ट पर ffmpeg 4.4 या उससे नया वर्ज़न चाहिए।',
