        'आउटपुट ऊँचाई चुनने पर कंपोज़ किया गया फ़्रेम आखिरी फ़िल्टर के रूप में स्केल होता है (lanczos, वर्गाकार पिक्सेल, चौड़ाई सम संख्या तक राउंड), कैप्शन बर्न होने के बाद, ताकि टेक्स्ट दोबारा बनाए जाने के बजाय चित्र के साथ स्केल हो। जिस ऊँचाई को आपका प्लान रेंडर नहीं कर सकता, उसे एरर के साथ अस्वीकार किया जाता है, कभी चुपचाप घटाया नहीं जाता।',
