      privacyNote: 'जब तक प्रोजेक्ट मौजूद है, Darkroom आपका मीडिया हमारे सर्वरों पर रखता है: अपलोड एसेट के रूप में मीडिया बिन में जाते हैं, सर्वर उनसे प्रीव्यू प्रॉक्सी, फ़िल्मस्ट्रिप और वेवफ़ॉर्म पीक रेंडर करता है, और एक्सपोर्ट ffmpeg द्वारा रेंडर होस्ट पर outputs/<jobId>/ में बनाए जाते हैं। जब आप कैप्शन माँगते हैं, तो ऑडियो हमारे अपने GPU पर Whisper को भेजा जाता है और बने हुए क्यू प्रोजेक्ट के साथ स्टोर होते हैं। प्रोजेक्ट दस्तावेज़, उसके एसेट, वर्ज़न और एक्सपोर्ट एडिटर से या आपके अकाउंट पेज से डिलीट किए जा सकते हैं। गेस्ट की फ़ाइलें 24 घंटे रखी जाती हैं; फ़्री अकाउंट के साथ आप 24 घंटे से 2 साल तक चुन सकते हैं। अपलोड किए गए वीडियो और ऑडियो हमारे अपने सर्वर पर एक स्वचालित विश्लेषण चरण से भी गुज़रते हैं। कुछ भी किसी थर्ड-पार्टी AI प्रदाता को नहीं भेजा जाता और किसी भी फ़ाइल का उपयोग किसी मॉडल को ट्रेन करने के लिए नहीं किया जाता।',
