      intro: 'हर फ़ोटो के अंदर एक दूसरा दस्तावेज़ छिपा होता है। पिक्सेल के साथ-साथ फ़ोन या कैमरा डिवाइस का ब्रांड और मॉडल, अक्सर उसका सीरियल नंबर, लेंस, एक्सपोज़र, शटर चलने का ठीक-ठीक सेकंड, फ़ाइल को आखिरी बार सेव करने वाला सॉफ़्टवेयर, एक छोटा प्रीव्यू थंबनेल, और लोकेशन सेवाएँ चालू होने पर उस जगह का अक्षांश, देशांतर और ऊँचाई भी लिख देता है जहाँ आप खड़े थे। यह टूल JPG, PNG, WebP या HEIC से यह सब पढ़ता है, हर टैग को इस आधार पर समूहों में दिखाता है कि वह क्या उजागर करता है, और फिर ExifTool के एक ही पास में सब कुछ हटा देता है, ताकि आप जो कॉपी शेयर करें उसमें केवल चित्र हो।',
