      intro: 'इमेज कंप्रेस करने का मतलब है उसे इस तरह री-एनकोड करना कि वही तस्वीर कम बाइट में आ जाए। यह पेज इमेज कन्वर्टर को इस तरह खोलता है कि क्वालिटी फ़ील्ड पहले से 80 पर सेट हो और आउटपुट फ़ॉर्मैट आपके अपलोड से मेल खाए, यानी JPG, JPG ही रहती है और WebP, WebP ही। हमारे सर्वर पर यह जॉब ImageMagick की एक कमांड है: फ़ाइल को उसके EXIF रोटेशन फ़्लैग के आधार पर अपने-आप सीधा किया जाता है, फिर -quality 80 के साथ लिखा जाता है, या 1 से 100 के बीच जो भी संख्या आप टाइप करें। JPG और WebP के लिए यही संख्या फ़ाइल साइज़ तय करती है। PNG के लिए इसे अनदेखा किया जाता है, क्योंकि PNG लॉसलेस है, इसलिए PNG फ़ोटो के लिए असली उपाय आउटपुट को JPG या WebP में बदलना है।',
