      intro: 'PDF अपलोड करें और हमारा सर्वर Poppler टूलकिट के pdftoppm से हर पेज रेंडर करता है, जो वही रास्टराइज़र है जिसे कई डेस्कटॉप PDF व्यूअर इस्तेमाल करते हैं। इस पेज का फ़ॉर्म JPG, सभी पेज और 150 DPI पर पहले से सेट है; आप DPI को 100, 200 या 300 में बदल सकते हैं, जॉब को पहले पेज तक सीमित कर सकते हैं, और JPEG क्वालिटी सेट कर सकते हैं, जो डिफ़ॉल्ट रूप से 90 होती है। सभी पेज चुनने पर आपको page-001.jpg, page-002.jpg आदि वाली ZIP मिलती है; केवल पहला पेज चुनने पर एक JPG मिलती है। रेंडरिंग से पहले pdfinfo पेज गिनता है, और 500 से ज़्यादा पेज होने पर जॉब अस्वीकार कर दिया जाता है।',
