          body: 'इनपुट: स्टीरियो ऑडियो के साथ 140 MB का 3 मिनट का 1920 x 1080 30 fps MP4, गेस्ट सीमाओं के भीतर। सेटिंग: 360p, 480p और 720p (डिफ़ॉल्ट चयन और गेस्ट जितना अधिकतम चुन सकता है), कोई कैप्शन या स्टोरीबोर्ड नहीं, tar.gz। हर स्तर 2 सेकंड के सेगमेंट में कटता है, प्रति स्तर 90, और 60 फ़्रेम के GOP के साथ ताकि हर सेगमेंट कीफ़्रेम पर शुरू हो। सूचीबद्ध बिटरेट पर स्तरों का वज़न ज़्यादा से ज़्यादा लगभग 360p के लिए 20 MB (800 + 96 kbps x 180 s), 480p के लिए 30 MB (1200 + 128 kbps) और 720p के लिए 66 MB (2800 + 128 kbps) होता है, छोटी 240p I-फ़्रेम प्लेलिस्ट से पहले कुल लगभग 116 MB, और आसान कंटेंट पर कम, क्योंकि एनकोड CRF पर आधारित है और बिटरेट एक ऊपरी सीमा है। नतीजे वाले पैकेज में 270 .ts सेगमेंट, तीन index.m3u8 फ़ाइलें और मास्टर होते हैं। समय तीन libx264 veryfast एनकोड में लगता है (हर एक 5400 फ़्रेम का), जो एक के बाद एक चलते हैं; 720p स्तर सबसे ज़्यादा समय लेता है।',
