      whenNotToUse: 'अगर आपको भेजने या एम्बेड करने के लिए बस एक छोटी फ़ाइल चाहिए, तो HLS में ट्रांसकोड न करें; कंप्रेसर यह एक ही पास में, बिना सेगमेंट और प्लेलिस्ट के कर देता है। लाइव इवेंट के लिए इसका उपयोग न करें, क्योंकि आउटपुट एक तैयार VOD प्लेलिस्ट है, लाइव ओरिजिन नहीं। अगर आपका सोर्स 360p से छोटा है, तो Premium के बिना लैडर नहीं बन सकती। और अगर आपका प्लेयर HLS समर्थन के बिना एक साधारण वीडियो टैग है, तो पहले आपको MP4 या hls.js जैसा प्लेयर चाहिए; अकेली master.m3u8 केवल Safari और Apple डिवाइस पर नेटिव रूप से चलती है।',
