        'प्री-क्लीन वेट हैं fbcnn_color.pth, scunet_color_real_psnr.pth (PSNR पर ट्रेन किया गया असली-नॉइज़ मॉडल, टेक्सचर गढ़ने वाला GAN वैरिएंट नहीं) और NAFNet-GoPro-width64.pth (मोशन डीब्लर, डीफ़ोकस नहीं)। ये 512-पिक्सेल टाइल में 32-पिक्सेल ओवरलैप के साथ चलते हैं और कभी आयाम नहीं बदलते। FBCNN, JPEG क्वालिटी फ़ैक्टर का अनुमान बिना देखे लगाता है, जब तक आप 1 से 100 के बीच कोई मान सेट न करें; कम संख्या का मतलब है ज़्यादा भारी कंप्रेशन मानना।',
        'GFPGAN साफ़ v1.4 आर्किटेक्चर का उपयोग करता है और बैकग्राउंड अप-सैंपलिंग बंद रहती है, इसलिए चेहरों के बाहर की इमेज मॉडल से सुधारी नहीं जाती, बस स्केल फ़ैक्टर से साधारण रूप से रीसाइज़ होती है; इससे तुलना ईमानदार रहती है। CodeFormer 0 से 1 तक का फ़िडेलिटी वेट w लेता है (डिफ़ॉल्ट 0.7): कम मान ज़्यादा सुंदर, ज़्यादा मान इनपुट के ज़्यादा करीब। CodeFormer ग़ैर-व्यावसायिक लाइसेंस के तहत आता है और एक सर्वर फ़्लैग के पीछे है जो डिफ़ॉल्ट रूप से बंद रहता है।',
        'चेन हर चेहरा मॉडल को सोर्स के अलावा हर अपस्केलर के आउटपुट पर भी 1x पर दोबारा चलाता है, इसलिए आउटपुट की गिनती है प्री-क्लीन + सामान्य + चेहरा + चेहरा x सामान्य। सर्वर एक जॉब को 12 आउटपुट तक सीमित करता है, एक समय में एक रेस्टोरेशन जॉब चलाता है, और हर मॉडल को टाइमआउट घोषित करने से पहले 1,800 सेकंड देता है।',
        'सर्वर हर मॉडल का रन टाइम अपने प्रति-मेगापिक्सेल सेकंड के डिफ़ॉल्ट मानों से आँकता है: FBCNN 3, SCUNet 8, NAFNet 6, Real-ESRGAN 2, SwinIR 12, HAT 18, GFPGAN 6, CodeFormer 8। इन्हीं से प्रगति के भार और UI का अनुमान बनते हैं; ये ट्यूनिंग मान हैं, कोई गारंटी नहीं।',
