          body: 'ऑटो मोड में PDF और DOCX के साथ नोटबुक पेजों की दो 4032 x 3024 फ़ोन फ़ोटो। तैयारी चरण दोनों को अपने-आप सही दिशा में घुमाकर PNG बनाता है और, क्योंकि मोड छपा हुआ नहीं है, realesrgan-x4plus से 2x अपस्केल करके 8064 x 6048 कर देता है। वर्गीकरण चरण qwen3-vl से हर पेज पर एक सवाल पूछता है, पहचान चरण हर पंक्ति के बाउंडिंग बॉक्स के साथ ट्रांसक्रिप्शन लौटाता है, और सत्यापन केवल चिह्नित टोकन दोबारा पढ़ता है। अगर किसी पेज में 30 पंक्तियाँ हैं और उनमें से 2 पर [?: ...] चिह्न हैं, तो 2 / 30, 15 प्रतिशत से कम है और पेज मध्यम भरोसे वाला चिह्नित होता है, illegibleCount 2 के साथ। PDF पेज प्रोसेस की गई इमेज हैं, जिनमें उन बॉक्स पर अदृश्य Helvetica पंक्तियाँ और फ़ुटर का ठप्पा होता है; Word फ़ाइल में बोल्ड सत्यापन नोट के नीचे शब्दशः टेक्स्ट होता है। समय है हमारे GPU पर हर पेज के लिए विज़न मॉडल के तीन लगातार पास; कुछ भी कहीं और नहीं चलता।',
