        'PII पैटर्न रेगुलर एक्सप्रेशन हैं: ईमेल (लोकल हिस्सा, @, और बिंदु वाला डोमेन जिसका TLD 2+ अक्षरों का हो); 10 अंकों का उत्तरी अमेरिकी फ़ोन नंबर, वैकल्पिक +1, कोष्ठक, बिंदुओं, स्पेस या डैश के साथ; डैश या स्पेस से अलग किए गए तीन, दो और चार अंक; 13 से 19 अंक, वैकल्पिक रूप से स्पेस या डैश से अलग (कार्ड नंबर); और मकान नंबर के बाद नाम और सड़क के प्रकार वाला शब्द। व्यक्तियों के नाम, जन्मतिथि या अमेरिका से बाहर के पहचानकर्ताओं के लिए कोई पैटर्न नहीं है।',
        'हर मेल खाने वाला बॉक्स हर तरफ़ max(3, 0.08 x उसकी चौड़ाई और ऊँचाई में से बड़ी) पिक्सेल बढ़ाया जाता है और इमेज की सीमा के भीतर रखा जाता है। ब्लैक बॉक्स भरे हुए काले भीतरी हिस्से के साथ cv2.rectangle इस्तेमाल करता है; पिक्सेलेट क्षेत्र को चौड़ाई में 12 ब्लॉक तक छोटा करके nearest-neighbour से वापस बड़ा करता है; ब्लर max(11, सबसे लंबी भुजा / 3) का गॉसियन कर्नेल इस्तेमाल करता है, जिसे विषम बनाया जाता है।',
        'OCR साफ़, क्षैतिज छपा टेक्स्ट सबसे अच्छी तरह पढ़ता है। हस्तलिपि, सजावटी फ़ॉन्ट, बहुत छोटा टेक्स्ट, ज़्यादा तिरछापन और कम कंट्रास्ट कॉन्फ़िडेंस घटाते हैं और ऐसा टेक्स्ट पूरी तरह छूट सकता है। "सारा टेक्स्ट" मोड उस पंक्ति को ठीक नहीं करता जिसे OCR ने कभी देखा ही नहीं।',
        'आउटपुट OpenCV लिखता है और AI आउटपुट के लिए कन्वर्टर का exiftool से वापस कॉपी करने वाला चरण छोड़ दिया जाता है, इसलिए मूल EXIF, GPS और कैमरा टैग नतीजे में नहीं जाते; यह टूल पिक्सेल के लिए है, मेटाडेटा के लिए नहीं।',
        'समाप्त होने पर स्क्रिप्ट redactions=N प्रिंट करती है; शून्य का नतीजा मतलब है कि OCR को कोई मेल खाता टेक्स्ट नहीं मिला, यह नहीं कि इमेज साफ़ थी।',
