          body: '128 kbps की AAC फ़ाइल प्रति सेकंड 16 KB होती है, इसलिए 720 सेकंड लगभग 11.5 MB हैं। बारह मिनट गेस्ट की 5 मिनट की सीमा से ज़्यादा है, इसलिए इसके लिए फ़्री अकाउंट (20 मिनट) चाहिए। ffmpeg पहले एक अस्थायी फ़ोल्डर में लगभग 69 MB (प्रति सेकंड 96,000 बाइट) का 48 kHz मोनो WAV लिखता है, जो जॉब खत्म होने पर हटा दिया जाता है। DeepFilterNet और पॉलिश चेन उसी पर चलते हैं, और MP3 एनकोडर नतीजे को 192 kbps पर लिखता है: लगभग 17 MB, जो इनपुट से बड़ा है क्योंकि 192 kbps उस दर से ज़्यादा है जिस पर मेमो रिकॉर्ड हुआ था। दोनों ffmpeg चरणों में कुछ सेकंड लगते हैं; DeepFilterNet पास सबसे ज़्यादा समय लेता है और रिकॉर्डिंग की लंबाई के साथ बढ़ता है।',
