      privacyNote: 'आपका गाना उसके जॉब फ़ोल्डर में स्टोर होता है और हमारे अपने GPU पर Demucs को दिया जाता है, जो वोकल और संगत के स्टेम एक स्क्रैच डायरेक्टरी में लिखता है; आपके डाउनलोड में केवल संगत एनकोड होती है, और जॉब खत्म होने पर स्क्रैच डायरेक्टरी (हटाए गए वोकल स्टेम सहित) डिलीट कर दी जाती है। एनकोड किया गया इंस्ट्रुमेंटल जॉब के साथ रखा जाता है। ऑडियो अपलोड हमारे सर्वर पर एक स्वचालित विश्लेषण चरण से भी गुज़रते हैं, जो आंतरिक समीक्षा के लिए Whisper से फ़ाइल ट्रांसक्राइब करता है, और वह समीक्षा जॉब के साथ रखी जाती है। कोई थर्ड-पार्टी AI प्रदाता शामिल नहीं होता। गेस्ट की फ़ाइलें 24 घंटे रखी जाती हैं; फ़्री अकाउंट के साथ आप 24 घंटे से 2 साल तक चुन सकते हैं।',
